<?php
namespace Azuriom\Plugin\GamingHubCore\Controllers\Admin; use Azuriom\Http\Controllers\Controller; use Azuriom\Plugin\GamingHubCore\Http\Requests\SaveExtensionSourceRequest; use Azuriom\Plugin\GamingHubCore\Models\ExtensionSource; use Azuriom\Plugin\GamingHubCore\Services\{ExtensionSourceManager,ExtensionUrlGuard}; use Illuminate\Http\RedirectResponse;
final class ExtensionSourceController extends Controller {public function __construct(private ExtensionSourceManager $manager,private ExtensionUrlGuard $guard){} public function store(SaveExtensionSourceRequest $r):RedirectResponse{$d=$r->validated();if($d['type']==='github')$this->guard->assertGithubRepository($d['url'],(bool)($d['allow_private_host']??false));else $this->guard->assertSafe($d['url'],(bool)($d['allow_private_host']??false));ExtensionSource::create(['source_id'=>$this->manager->makeId($d['name']),'type'=>$d['type'],'name'=>$d['name'],'url'=>$d['url'],'trust_level'=>($d['trusted']??false)?'trusted':'untrusted','trusted'=>(bool)($d['trusted']??false),'enabled'=>(bool)($d['enabled']??false),'allow_prereleases'=>(bool)($d['allow_prereleases']??false),'allow_private_host'=>(bool)($d['allow_private_host']??false),'added_by'=>$r->user()->getKey()]);return back()->with('success','Extension source added.');}public function refresh(ExtensionSource $source):RedirectResponse{$this->manager->refresh($source,true);return back()->with('success','Extension source refreshed.');}public function toggle(ExtensionSource $source):RedirectResponse{if($source->type==='official'&&$source->enabled) return back()->withErrors('The official registry cannot be disabled in v0.6.0.');$source->update(['enabled'=>!$source->enabled]);$this->manager->invalidate($source);return back();}public function trust(ExtensionSource $source):RedirectResponse{if($source->type==='official')return back();$source->update(['trusted'=>!$source->trusted,'trust_level'=>$source->trusted?'untrusted':'trusted']);return back();}public function destroy(ExtensionSource $source):RedirectResponse{abort_if($source->type==='official',403);$this->manager->invalidate($source);$source->delete();return back();}}
